@register.simple_tag
def ui_art(key):
    x, y, width, height = CROPS[key]
    shapes = {
        'shop': '910,378 1071,378 1071,484 861,484 861,433 910,433',
        'detailing': '910,500 1075,500 1075,610 862,610 862,547 910,547',
        'ag': '1298,380 1406,380 1406,485 1184,485 1184,433 1298,433',
        'kits': '245,503 390,503 390,610 121,610 121,532 245,532',
        'repair': '575,502 735,502 735,610 512,610 512,537 575,537',
    }
    points = shapes.get(key, f'{x},{y} {x+width},{y} {x+width},{y+height} {x},{y+height}')
    return format_html(
        '<svg class="art" aria-hidden="true" focusable="false" viewBox="{}" preserveAspectRatio="xMidYMid meet"><defs><clipPath id="art-{}"><polygon points="{}"/></clipPath></defs><image clip-path="url(#art-{})" href="{}" width="1536" height="1024"/></svg>',
        ' '.join(map(str, CROPS[key])), key, points, key, static('interface/approved-desktop.png'))
